con = sqlite3.connect('src/results.db')
con.execute('PRAGMA foreign_keys = ON')
with con:
    for topic, text in NOTES:
        cur = con.execute('INSERT INTO notes(topic,text) VALUES(?,?)', (topic, text))
        print('Заметка:', cur.lastrowid, '-', topic)
con.close()
